-- ═══════════════════════════════════════════════════════════════════════════
-- ConnectSphere seed data — event-service (event_db)
-- Generated against schema-updated.prisma (proposed contract).
-- Load order (cross-service references are logical only — no DB-level FKs across services):
--   1. user_db  2. auth_db  3. venue_db  4. event_db  5. booking_db
--   6. attendance_db  7. messaging_db  8. notification_db
-- Dataset "as of" 2026-09-25. All timestamps are UTC (Asia/Singapore = UTC+8).
-- Idempotent: every insert uses ON CONFLICT ("id") DO NOTHING.
-- Same-service FKs: coordinator_assignments.requestId, events.eventRequestId -> event_requests.id
-- Cross-service: organiserId / reviewedById / coordinatorId / assignedById / confirmedById -> user_db.users.id
-- ═══════════════════════════════════════════════════════════════════════════

BEGIN;

-- event_requests (parent — insert first)
ON CONFLICT ("id") DO NOTHING;

-- coordinator_assignments (CS-30: one current row per request; ER07 intentionally unassigned)
ON CONFLICT ("id") DO NOTHING;

-- events (one per APPROVED request)
ON CONFLICT ("id") DO NOTHING;
COMMIT;
