INSERT INTO "event_requests" ("id", "title", "purpose", "description", "proposedDate", "expectedAttendees", "timeZone", "venueType", "minimumCapacity", "preferredLayout", "venueRequirements", "accessibilityNeeds", "accessibilityDetails", "equipmentNeeds", "technicalDetails", "registrationEnabled", "registrationDetails", "operationKey", "status", "submittedAt", "organiserId", "reviewedById", "reviewedAt", "decisionNotes", "createdAt", "updatedAt") VALUES
  ('e1000000-0000-4000-8000-000000000001', 'Nexus Labs Product Launch 2026', 'Product launch', 'Launch of the Nexus Labs Aurora analytics platform with keynote, live demos and partner showcase.', '2026-08-14 01:00:00.000', 250, 'Asia/Singapore', 'Convention hall', 250, 'Theatre', 'Stage with rear projection; separate demo booth area.', ARRAY['Wheelchair access', 'Reserved seating']::text[], 'Four wheelchair spaces near the front row.', ARRAY['Projector', 'Wireless microphones', 'Livestream setup']::text[], 'Dual 4K projectors; livestream to YouTube.', FALSE, '', NULL, 'APPROVED', '2026-06-02 03:15:00.000', 'a1000000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000005', '2026-06-05 06:30:00.000', 'Approved. Venue shortlist: Marina Convention Centre Hall A.', '2026-06-01 02:00:00.000', '2026-06-05 06:30:00.000'),  -- ER01 APPROVED by Sarah Tan
  ('e1000000-0000-4000-8000-000000000002', 'BrightPath Parent-Teacher Symposium', 'Education symposium', 'Afternoon symposium on student wellbeing with panel discussions and breakout sessions for parents and teachers.', '2026-10-22 05:00:00.000', 150, 'Asia/Singapore', 'Ballroom', 150, 'Banquet', 'Space for four breakout clusters.', ARRAY['Wheelchair access', 'Hearing loop']::text[], 'Two attendees use hearing aids.', ARRAY['PA system', 'Wireless microphones']::text[], 'Four handheld mics for panel Q&A.', FALSE, '', NULL, 'APPROVED', '2026-08-11 02:00:00.000', 'a1000000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000006', '2026-08-14 04:00:00.000', 'Approved. Please share final agenda two weeks before the event.', '2026-08-10 01:30:00.000', '2026-08-14 04:00:00.000'),  -- ER02 APPROVED by Daniel Lim
  ('e1000000-0000-4000-8000-000000000003', 'GreenLeaf Sustainability Forum', 'Industry forum', 'Half-day forum on corporate sustainability reporting featuring regional ESG leaders.', '2026-11-12 01:30:00.000', 180, 'Asia/Singapore', 'Auditorium', 180, 'Theatre', 'Tiered seating preferred.', ARRAY['Wheelchair access', 'Hearing loop']::text[], '', ARRAY['Projector', 'PA system', 'Recording equipment']::text[], 'Sessions to be recorded for on-demand viewing.', FALSE, '', NULL, 'APPROVED', '2026-08-26 01:00:00.000', 'a1000000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000007', '2026-09-03 07:00:00.000', 'Approved after handover. Venue booking in progress.', '2026-08-25 03:00:00.000', '2026-09-03 07:00:00.000'),  -- ER03 APPROVED by Priya Raman
  ('e1000000-0000-4000-8000-000000000004', 'Orbit Fintech Investor Roadshow', 'Investor briefing', 'Closed-door briefing for prospective Series B investors.', '2026-10-08 02:00:00.000', 60, 'Asia/Singapore', 'Seminar room', 60, 'Classroom', 'Private room, no signage outside.', '{}'::text[], '', ARRAY['Projector', 'Video conferencing']::text[], 'Zoom link for two remote investors.', FALSE, '', NULL, 'APPROVED', '2026-07-21 01:30:00.000', 'a1000000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000005', '2026-07-24 05:00:00.000', 'Approved.', '2026-07-20 02:00:00.000', '2026-07-24 05:00:00.000'),  -- ER04 APPROVED by Marcus Wong
  ('e1000000-0000-4000-8000-000000000005', 'Nexus Labs Developer Meetup', 'Community meetup', 'Evening meetup with lightning talks on the Aurora SDK, followed by networking.', '2026-10-03 11:00:00.000', 70, 'Asia/Singapore', 'Terrace', 70, 'Cocktail', 'Standing tables and a small presentation corner.', ARRAY['Wheelchair access']::text[], '', ARRAY['PA system', 'Projector']::text[], 'HDMI and USB-C adapters needed.', FALSE, '', NULL, 'APPROVED', '2026-08-01 08:00:00.000', 'a1000000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000006', '2026-08-04 02:30:00.000', 'Approved.', '2026-08-01 04:00:00.000', '2026-08-04 02:30:00.000'),  -- ER05 APPROVED by Sarah Tan
  ('e1000000-0000-4000-8000-000000000006', 'BrightPath Year-End Graduation Ceremony', 'Graduation ceremony', 'Graduation ceremony for 180 graduating students and their families.', '2026-12-04 02:00:00.000', 400, 'Asia/Singapore', 'Convention hall', 400, 'Theatre', 'Stage with steps on both sides; photo backdrop.', ARRAY['Wheelchair access', 'Reserved seating']::text[], 'Elderly guests expected; ramp access to stage required.', ARRAY['PA system', 'Stage lighting', 'Projector']::text[], 'Slideshow of graduates on loop before ceremony.', FALSE, '', NULL, 'SUBMITTED', '2026-09-16 01:00:00.000', 'a1000000-0000-4000-8000-000000000002', NULL, NULL, NULL, '2026-09-15 02:00:00.000', '2026-09-16 01:00:00.000'),  -- ER06 SUBMITTED by Daniel Lim
  ('e1000000-0000-4000-8000-000000000007', 'Orbit Fintech Hackathon', 'Hackathon', '24-hour hackathon on open-banking APIs with prizes and mentor sessions.', '2026-11-28 01:00:00.000', 120, 'Asia/Singapore', 'Auditorium', 120, 'Classroom', 'Overnight access required.', '{}'::text[], '', ARRAY['Wi-Fi', 'Power strips', 'Projector']::text[], 'Minimum 500 Mbps Wi-Fi; power at every table.', FALSE, '', NULL, 'SUBMITTED', '2026-09-24 02:30:00.000', 'a1000000-0000-4000-8000-000000000004', NULL, NULL, NULL, '2026-09-23 06:00:00.000', '2026-09-24 02:30:00.000'),  -- ER07 SUBMITTED by Marcus Wong
  ('e1000000-0000-4000-8000-000000000008', 'GreenLeaf Charity Gala Dinner', 'Fundraising dinner', 'Annual charity gala dinner with auction in support of coastal conservation.', '2026-12-12 11:30:00.000', 220, 'Asia/Singapore', 'Ballroom', 220, 'Banquet', 'Round tables of 10.', '{}'::text[], '', ARRAY['PA system', 'Stage lighting']::text[], '', FALSE, '', NULL, 'RETURNED_FOR_AMENDMENT', '2026-09-06 03:00:00.000', 'a1000000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000007', '2026-09-10 08:00:00.000', 'Please confirm catering headcount and add accessibility requirements before resubmitting.', '2026-09-05 02:00:00.000', '2026-09-10 08:00:00.000'),  -- ER08 RETURNED_FOR_AMENDMENT by Priya Raman
  ('e1000000-0000-4000-8000-000000000009', 'Orbit Fintech Rooftop Networking Night', 'Networking', 'Rooftop networking night for fintech founders and investors.', '2026-10-30 11:00:00.000', 600, 'Asia/Singapore', 'Rooftop', 600, 'Cocktail', 'Open-air rooftop with bar.', '{}'::text[], '', ARRAY['PA system']::text[], '', FALSE, '', NULL, 'REJECTED', '2026-09-01 06:00:00.000', 'a1000000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000006', '2026-09-04 03:00:00.000', 'Rejected: expected attendance of 600 exceeds the capacity of every partner venue (max 500).', '2026-09-01 05:00:00.000', '2026-09-04 03:00:00.000'),  -- ER09 REJECTED by Marcus Wong
  ('e1000000-0000-4000-8000-000000000010', 'Nexus Labs Q1 Town Hall', 'Internal town hall', 'Quarterly all-hands with leadership updates and Q&A.', '2027-01-15 02:00:00.000', 180, 'Asia/Singapore', 'Auditorium', 180, 'Theatre', '', ARRAY['Wheelchair access']::text[], '', ARRAY['Projector', 'PA system']::text[], '', FALSE, '', NULL, 'DRAFT', NULL, 'a1000000-0000-4000-8000-000000000001', NULL, NULL, NULL, '2026-09-20 03:00:00.000', '2026-09-22 04:10:00.000'),  -- ER10 DRAFT by Sarah Tan
  ('e1000000-0000-4000-8000-000000000011', 'BrightPath STEM Fair', '', 'Student STEM project showcase (details TBC).', '2027-03-06 01:00:00.000', 100, 'Asia/Singapore', '', NULL, NULL, '', '{}'::text[], '', '{}'::text[], '', FALSE, '', NULL, 'DRAFT', NULL, 'a1000000-0000-4000-8000-000000000002', NULL, NULL, NULL, '2026-09-24 09:00:00.000', '2026-09-24 09:00:00.000'),  -- ER11 DRAFT by Daniel Lim
  ('e1000000-0000-4000-8000-000000000012', 'GreenLeaf Beach Cleanup Volunteer Briefing', 'Volunteer briefing', 'Safety and logistics briefing for volunteers ahead of the East Coast beach cleanup.', '2026-07-18 01:00:00.000', 40, 'Asia/Singapore', 'Seminar room', 40, 'Classroom', '', ARRAY['Wheelchair access']::text[], '', ARRAY['Projector']::text[], '', FALSE, '', NULL, 'APPROVED', '2026-06-10 04:00:00.000', 'a1000000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000007', '2026-06-12 06:00:00.000', 'Approved.', '2026-06-10 02:00:00.000', '2026-06-12 06:00:00.000')  -- ER12 APPROVED by Priya Raman
